p=BASE/'coverage.json';rows=__import__('json').loads(p.read_text(encoding='utf8'))
for r in rows:
    for x in r['included']:
        if x['card_id']=='weisili_ba_tu':x['card_id']='weisili_batu'
        if x['card_id']=='weisili_qing_long':x['card_id']='yuanzhenxia_qinglong'
